# 继承与多态

## 继承
Swift中只有**类**支持继承，一个类可以继承另一个类的属性和方法：

```swift
class Vehicle {
    var speed = 0.0
    func describe() -> String {
        return "速度为\(speed)km/h的交通工具"
    }
}

class Car: Vehicle {
    var gear = 1
    override func describe() -> String {
        return "速度为\(speed)km/h，档位\(gear)的汽车"
    }
}
```

子类使用 `: 父类名` 语法继承，可以添加新属性和方法。

## 重写 override
子类可以重写父类的方法、属性和下标，必须使用 `override` 关键字：

```swift
class Animal {
    func speak() -> String { "..." }
}

class Dog: Animal {
    override func speak() -> String { "汪汪" }
}

class Cat: Animal {
    override func speak() -> String { "喵喵" }
}
```

使用 `super` 访问父类实现：
```swift
override func describe() -> String {
    return super.describe() + "，额外信息"
}
```

## final 关键字
`final` 防止类被继承或方法被重写：

```swift
final class ImmutableClass { }     // 不可被继承
class Parent {
    final func cannotOverride() { }  // 不可被重写
}
```

## 类型转换
- `is`：类型检查，返回Bool
- `as?`：安全转换，返回Optional
- `as!`：强制转换，失败则崩溃

```swift
let animals: [Animal] = [Dog(), Cat(), Dog()]
for animal in animals {
    if let dog = animal as? Dog {
        print("这是一只狗：\(dog.speak())")
    }
}
```

## 多态
多态允许通过父类引用调用子类实现：
```swift
let pets: [Animal] = [Dog(), Cat()]
for pet in pets {
    print(pet.speak())  // 分别输出 "汪汪" 和 "喵喵"
}
```

## 练习
定义类 `Shape` 及其子类 `Circle` 和 `Rectangle`。Shape有方法 `area() -> Double` 返回0，Circle有属性 `radius`，Rectangle有属性 `width` 和 `height`，各自重写 `area()` 方法。

starter_code:
class Shape {
    func area() -> Double {
        return 0.0
    }
}

class Circle: Shape {
    var radius: Double
    init(radius: Double) {
        self.radius = radius
    }
    // 重写area方法
}

class RectangleShape: Shape {
    var width: Double
    var height: Double
    init(width: Double, height: Double) {
        self.width = width
        self.height = height
    }
    // 重写area方法
}

solution_code:
class Shape {
    func area() -> Double {
        return 0.0
    }
}

class Circle: Shape {
    var radius: Double
    init(radius: Double) {
        self.radius = radius
    }
    override func area() -> Double {
        return .pi * radius * radius
    }
}

class RectangleShape: Shape {
    var width: Double
    var height: Double
    init(width: Double, height: Double) {
        self.width = width
        self.height = height
    }
    override func area() -> Double {
        return width * height
    }
}

